import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)
    t = int(next(iterator))
    results = []
    for _ in range(t):
        x = int(next(iterator))
        if x == 2:
            results.append(1)
        elif x == 3:
            results.append(1)
        elif x == 4:
            results.append(1)
        elif x == 5:
            results.append(1)
        elif x == 6:
            results.append(1)
        elif x == 7:
            results.append(1)
        elif x == 8:
            results.append(2)
        elif x == 9:
            results.append(2)
        elif x == 10:
            results.append(2)
        elif x == 11:
            results.append(2)
        elif x == 12:
            results.append(2)
        elif x == 13:
            results.append(3)
        else:
            # For larger x, we can always use rolls of 2 and 7.
            # We want to find k such that there exist a_i in [2,7] with sum = x.
            # A simple constructive approach:
            # Use as many 7s as possible, then adjust with 2s.
            # Let k be the number of rolls.
            # Minimum sum with k rolls = 2*k
            # Maximum sum with k rolls = 7*k
            # So we need 2*k <= x <= 7*k.
            # We can iterate k starting from ceil(x/7) upwards until 2*k <= x.
            k = (x + 6) // 7
            while 2 * k > x:
                k += 1
            results.append(k)
    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    solve()
